function reverseList(head) {
let stack = [];
let temp = head;
// push all nodes into stack
while (temp !== null) {
stack.push(temp);
temp = temp.next;
}
// make the last node as new head of the linked list
if (stack.length > 0) {
head = stack.pop();
temp = head;
// pop all the nodes and append to the linked list
while (stack.length > 0) {
temp.next = stack.pop();
temp = temp.next;
}
temp.next = null;
}
return head;
}
