def bubble_sort(head):
if not head: return None
end = None
while end != head.next:
curr = head
while curr.next != end:
next_node = curr.next
if curr.data > next_node.data:
curr.data, next_node.data = next_node.data,
curr.data
curr = curr.next
end = curr
return head

