def infix_to_postfix(exp):
precedence = {'+':1, '-':1, '*':2,
'/':2, '^':3}
stack = []
output = ""
for char in exp:
if char.isalnum():
output += char
elif char == '(':
stack.append('(')
elif char == ')':
while stack and stack[-1] !=
'(':
output += stack.pop()
stack.pop()
else:
while stack and stack[-1] !=
'(' and precedence[char] <=
precedence.get(stack[-1], 0):
output += stack.pop()
stack.append(char)
while stack:
output += stack.pop()
return output
print(infix_to_postfix("a+b*(c^d-e)"))
