def round_robin(tasks, quantum):
q = deque(tasks)
time = 0
while q:
task_name, remaining_time =
q.popleft()
if remaining_time <= quantum:
time += remaining_time
print(f"Task {task_name}
finished at {time}")
else:
time += quantum
q.append((task_name,
remaining_time - quantum))
